use crate::{catalog,model::*,rules::*,unit_support::*};
fn grave(g:&mut Game,print:&str,seat:usize)->String{let c=g.make_card(print,seat);let id=c.id.clone();g.players[seat].graveyard.push(c);id}
fn deploy(g:&mut Game,extra:bool)->String{let id=held(g,"BQ029",0);act(g,0,Action{card_id:Some(id.clone()),region:Some(0),option:extra.then(||"pay-extra-1".into()),..Action::new("deploy")});id}
fn pending(g:&mut Game){for _ in 0..64{if g.pending.is_some(){restore(g);return;}if !g.effects.is_empty(){g.drive().unwrap();}else if !g.stack.is_empty(){pass(g);}else{panic!("no pending or execution");}}panic!("pending bounded");}
fn feed(g:&mut Game,blood:&str){pending(g);assert!(matches!(&g.pending.as_ref().unwrap().resolution,ChoiceResolution::Declare{declaration,..} if declaration.ability.key=="batch3-bq029-feed"));choose(g,vec!["accept".into()]);pending(g);assert_eq!(g.pending.as_ref().unwrap().choice.kind,"batch3-blood");choose(g,vec![blood.into()]);}
fn settle(g:&mut Game){for _ in 0..128{if let Some(p)=&g.pending{let ids=match &p.resolution{ChoiceResolution::Batch3EntryOrder{..}=>vec![p.choice.options[0].id.clone()],ChoiceResolution::Frame{choice:FrameChoice::BloodFeed{..},..}=>vec![p.choice.options[0].id.clone()],_=>vec![]};choose(g,ids);}else if !g.stack.is_empty(){pass(g);}else if !g.effects.is_empty(){g.drive().unwrap();}else{restore(g);return;}}panic!("settlement bounded");}
#[test]fn batch3_bq029_real_extra_payment_is_separate_and_enters_with_printed_icons_and_blood(){
    let mut g=game();fund(&mut g,0,"JC029",2);fund(&mut g,0,"JC125",1);let blood=grave(&mut g,"XQ14",0);let old=deploy(&mut g,true);let f=g.stack.last().unwrap().frame.as_ref().unwrap();assert!(matches!(f.already_paid.as_slice(),[PaidCost::Assets(base),PaidCost::BQ029ExtraAssets(extra)] if base.len()==2 && extra.len()==1 && !base.contains(&extra[0])));feed(&mut g,&blood);assert_eq!(g.resources(0),0);let c=&g.regions[0].cards[0];assert_ne!(c.id,old);assert_eq!(g.current_icons(c,0),Icons{combat:2,..Icons::default()});assert_eq!(g.defense(c,0),2);restore(&mut g);
}
#[test]fn batch3_bq029_unaffordable_extra_or_polluted_declaration_rejects_atomically_and_candidates_offer_both_prices(){
    let mut g=game();fund(&mut g,0,"JC029",2);let id=held(&mut g,"BQ029",0);let action=Action{card_id:Some(id.clone()),region:Some(0),option:Some("pay-extra-1".into()),..Action::new("deploy")};reject(&mut g,0,action.clone());assert!(g.players[0].assets.iter().all(|a|!a.exhausted));assert!(g.legal_actions(0).iter().any(|a|a.action.card_id.as_deref()==Some(&id) && a.action.kind=="deploy" && a.action.option.is_none()));assert!(!g.legal_actions(0).iter().any(|a|a.action.card_id.as_deref()==Some(&id) && a.action.option.is_some()));fund(&mut g,0,"JC125",1);
    assert!(g.legal_actions(0).iter().any(|a|a.action==action));reject(&mut g,0,Action{selected:Some(vec!["unrelated".into()]),..action});
}
#[test]fn batch3_bq029_no_extra_or_personal_moon_has_no_entry_feed_and_allied_moon_does_not_substitute(){
    let mut g=game();fund(&mut g,0,"JC029",2);g.players[1].society_zone.secrecy=1;let blood=grave(&mut g,"XQ14",0);deploy(&mut g,false);top(&mut g);assert!(g.pending.is_none());assert!(g.players[0].graveyard.iter().any(|c|c.id==blood));assert!(g.attachments.is_empty());g.players[0].society_zone.secrecy=1;assert!(g.effects.is_empty());restore(&mut g);
}
#[test]fn batch3_bq029_personal_moon_at_entry_and_resolution_qualifies_but_loss_cancels_feed_without_refund(){
    for keep in [false,true]{let mut g=game();fund(&mut g,0,"JC029",2);let blood=grave(&mut g,"XQ14",0);g.players[0].society_zone.secrecy=1;deploy(&mut g,false);pending(&mut g);choose(&mut g,vec!["accept".into()]);if !keep{g.players[0].society_zone.secrecy=0;top(&mut g);assert!(g.pending.is_none());assert!(g.attachments.is_empty());}else{pending(&mut g);choose(&mut g,vec![blood]);assert_eq!(g.attachments.len(),1);}assert_eq!(g.resources(0),0);restore(&mut g);}
}
#[test]fn batch3_bq029_moon_gained_during_paid_deploy_response_is_checked_at_actual_entry(){
    let mut g=game();fund(&mut g,0,"JC029",2);let blood=grave(&mut g,"XQ14",0);deploy(&mut g,false);g.players[0].society_zone.secrecy=1;feed(&mut g,&blood);assert_eq!(g.attachments.len(),1);restore(&mut g);
}
#[test]fn batch3_bq029_paid_extra_survives_moon_loss_and_current_controller_chooses_the_blood(){
    let mut g=game();fund(&mut g,0,"JC029",3);let blood=grave(&mut g,"BQ040",2);deploy(&mut g,true);pending(&mut g);choose(&mut g,vec!["accept".into()]);let id=g.regions[0].cards[0].id.clone();g.board_mut(&id).unwrap().controller=2;pending(&mut g);assert_eq!(g.pending.as_ref().unwrap().seat,2);choose(&mut g,vec![blood]);assert_eq!((g.attachments[0].card.owner,g.attachments[0].card.controller),(2,2));assert_eq!(g.resources(0),0);restore(&mut g);
}
#[test]fn batch3_bq029_nonasset_is_a_personal_sun_condition_and_inactive_or_ally_sun_allows_asset(){
    for personal_sun in [false,true]{let mut g=game();let id=held(&mut g,"BQ029",0);g.players[0].society_zone.exposure=u32::from(personal_sun);g.players[1].society_zone.exposure=1;let a=Action{card_id:Some(id.clone()),..Action::new("asset")};if personal_sun{reject(&mut g,0,a);assert!(!g.legal_actions(0).iter().any(|a|a.action.kind=="asset" && a.action.card_id.as_deref()==Some(&id)));}else{act(&mut g,0,a);assert!(g.players[0].assets.iter().any(|c|c.definition=="BQ029"));}restore(&mut g);}
}
#[test]fn batch3_bq029_extra_is_not_available_on_paid_reveal_and_does_not_follow_a_hidden_new_identity(){
    let mut g=game();fund(&mut g,0,"JC029",3);let blood=grave(&mut g,"XQ14",0);deploy(&mut g,true);feed(&mut g,&blood);let id=g.regions[0].cards[0].id.clone();let hidden=g.hide_in_place_successor(&id).unwrap();fund(&mut g,0,"JC029",2);
    reject(&mut g,0,Action{card_id:Some(hidden.id.clone()),option:Some("pay-extra-1".into()),..Action::new("reveal")});act(&mut g,0,Action{card_id:Some(hidden.id),..Action::new("reveal")});settle(&mut g);assert!(g.attachments.is_empty());assert!(g.players[0].graveyard.iter().any(|c|c.definition=="XQ14"));restore(&mut g);
}
#[test]fn batch3_bq029_printed_raid_combines_with_existing_jc038_grant_and_resolves_real_damage(){
    let mut g=game();field(&mut g,"JC038",0);let enemy=field(&mut g,"JC125",2);let id=field(&mut g,"BQ029",0);let hidden=g.hide_in_place_successor(&id).unwrap();fund(&mut g,0,"JC029",2);act(&mut g,0,Action{card_id:Some(hidden.id),..Action::new("reveal")});pending(&mut g);assert!(g.pending.as_ref().unwrap().choice.title.contains("袭击2"));choose(&mut g,vec![enemy.clone()]);top(&mut g);assert!(g.board(&enemy).is_none());restore(&mut g);
}
#[test]fn batch3_bq029_forged_reused_extra_assets_duplicate_entry_and_changed_qualified_observation_are_rejected(){
    let mut g=game();fund(&mut g,0,"JC029",3);deploy(&mut g,true);let mut bad=g.clone();let f=bad.stack.last_mut().unwrap().frame.as_mut().unwrap();let first=if let PaidCost::Assets(ids)=&f.already_paid[0]{ids[0].clone()}else{panic!()};f.already_paid[1]=PaidCost::BQ029ExtraAssets(vec![first]);assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());pending(&mut g);let p=g.pending.clone().unwrap();let ChoiceResolution::Declare{declaration:d,..}=p.resolution else{panic!()};let mut bad=g.clone();bad.effects.push_back(Effect::Declare{declaration:d});assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());
    let mut bad=g.clone();if let ChoiceResolution::Declare{declaration,..}=&mut bad.pending.as_mut().unwrap().resolution{if let Op::BQ029SelfFeed{observation:Some(o)}=&mut declaration.ability.ops[0]{o.extra=None;o.moon_at_entry=0;}}assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());
}
#[test]fn batch3_entry_order_bq029_and_bq037_share_limited_blood_according_to_chosen_stack_order(){
    for self_first in [false,true]{let mut g=game();let source=field(&mut g,"BQ037",0);grave(&mut g,"XQ14",0);grave(&mut g,"BQ040",0);fund(&mut g,0,"JC029",2);g.players[0].society_zone.secrecy=1;deploy(&mut g,false);pending(&mut g);assert_eq!(g.pending.as_ref().unwrap().choice.kind,"batch3-entry-order");let suffix=if self_first{"batch3-bq029-feed"}else{"batch3-bq037-feed"};let key=g.pending.as_ref().unwrap().choice.options.iter().find(|o|o.id.ends_with(suffix)).unwrap().id.clone();choose(&mut g,vec![key]);choose(&mut g,vec!["accept".into()]);assert!(matches!(&g.pending.as_ref().unwrap().resolution,ChoiceResolution::Declare{..}));choose(&mut g,vec!["accept".into()]);settle(&mut g);let incoming=g.regions[0].cards.iter().find(|c|c.definition=="BQ029").unwrap().id.clone();assert_eq!(g.attachments.iter().filter(|a|a.host_id==incoming).count(),if self_first{1}else{2});assert_eq!(g.attachments.iter().filter(|a|a.host_id==source).count(),usize::from(self_first));assert!(g.entry_order_groups.is_empty());restore(&mut g);}
}
#[test]fn batch3_entry_order_keeps_existing_jz22_entry_program_in_normal_queue_and_checks_exact_references(){
    let mut g=game();field(&mut g,"BQ037",0);let c=g.make_card("JZ22",0);let id=c.id.clone();g.players[0].graveyard.push(c);g.world_graveyard_entry(0,0,&id).unwrap();g.drive().unwrap();restore(&mut g);let p=g.pending.clone().unwrap();assert_eq!(p.choice.kind,"batch3-entry-order");assert_eq!(p.choice.options.len(),2);
    let mut bad=g.clone();bad.entry_order_groups.clear();assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());let mut bad=g.clone();bad.pending.as_mut().unwrap().choice.options.pop();assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());reject(&mut g,0,Action{choice_id:Some(p.choice.id),selected:Some(vec![p.choice.options[0].id.clone()]),region:Some(4),..Action::new("choose")});
    let key=p.choice.options.iter().find(|o|o.label.starts_with(&catalog::card("JZ22").name)).unwrap().id.clone();choose(&mut g,vec![key]);choose(&mut g,vec!["accept".into()]);choose(&mut g,vec![]);top(&mut g);assert_eq!(g.regions[0].influence[0],1);assert!(g.entry_order_groups.is_empty());restore(&mut g);
}
#[test]fn batch3_blood_actual_entry_notifies_existing_bq030_observer_once_per_attachment(){
    let mut g=game();field(&mut g,"BQ037",0);field(&mut g,"BQ030",0);let a=grave(&mut g,"XQ14",0);let b=grave(&mut g,"BQ040",0);g.players[0].deck=(0..5).map(|_|g.make_card("JC125",0)).collect();let id=field(&mut g,"JC029",0);g.enter_triggers(0,"JC029",&id,false);pending(&mut g);choose(&mut g,vec!["accept".into()]);pending(&mut g);choose(&mut g,vec![a]);choose(&mut g,vec![b]);let before=g.players[0].hand.len();
    for _ in 0..64{if let Some(p)=g.pending.clone(){assert!(matches!(&p.resolution,ChoiceResolution::Declare{declaration,..} if declaration.source.card.definition=="BQ030"));choose(&mut g,vec![p.choice.options[0].id.clone()]);}else if !g.stack.is_empty(){pass(&mut g);}else if !g.effects.is_empty(){g.drive().unwrap();}else{break;}}assert_eq!(g.players[0].hand.len(),before+2);restore(&mut g);
}
